@import 'tailwindcss';
@plugin "@tailwindcss/typography";

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  --color-primary: var(--aw-color-primary);
  --color-secondary: var(--aw-color-secondary);
  --color-accent: var(--aw-color-accent);
  --color-default: var(--aw-color-text-default);
  --color-muted: var(--aw-color-text-muted);

  --font-sans:
    var(--aw-font-sans, ui-sans-serif), ui-sans-serif, system-ui, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji',
    'Segoe UI Symbol', 'Noto Color Emoji';
  --font-serif: var(--aw-font-serif, ui-serif), ui-serif, Georgia, Cambria, 'Times New Roman', Times, serif;
  --font-heading:
    var(--aw-font-heading, ui-sans-serif), ui-sans-serif, system-ui, sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji',
    'Segoe UI Symbol', 'Noto Color Emoji';

  --animate-fade: fadeInUp 1s both;

  @keyframes fadeInUp {
    0% {
      opacity: 0;
      transform: translateY(2rem);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

/* Syne font needs extra line-height for descenders (g, y, p, q).
   Higher specificity (element+class) overrides text-4xl's built-in line-height. */
h1.font-heading,
h2.font-heading,
h3.font-heading,
h4.font-heading,
h5.font-heading,
h6.font-heading,
p.font-heading,
span.font-heading {
  line-height: 1.3;
}

@utility bg-page {
  background-color: var(--aw-color-bg-page);
}

@utility bg-dark {
  background-color: var(--aw-color-bg-page-dark);
}

@utility bg-light {
  background-color: var(--aw-color-bg-page);
}

@utility text-page {
  color: var(--aw-color-text-default);
}

@utility text-muted {
  color: var(--aw-color-text-muted);
}

@variant intersect (&:not([no-intersect]));

.btn {
  @apply inline-flex items-center justify-center rounded-md border border-white/15 bg-transparent font-medium text-center text-base leading-snug transition py-3 px-6 md:px-8 ease-in duration-200 focus:ring-2 hover:bg-white/[0.06] hover:border-white/25 text-slate-200 dark:text-slate-200 dark:border-white/15 dark:hover:bg-white/[0.06] dark:hover:border-white/25 cursor-pointer;
  --tw-ring-color: rgba(212, 168, 83, 0.4);
  ring-offset-width: 2px;
  ring-offset-color: #0a0a0a;
}

.btn-primary {
  @apply font-semibold bg-primary text-gray-950 border-primary hover:bg-secondary hover:border-secondary hover:text-gray-950 dark:text-gray-950 dark:bg-primary dark:border-primary dark:hover:border-secondary dark:hover:bg-secondary;
}

.btn-secondary {
  /* inherits from .btn */
}

.btn-tertiary {
  @apply border-none shadow-none text-muted hover:text-white dark:text-gray-400 dark:hover:text-white;
}

#header.scroll > div:first-child {
  @apply bg-page md:backdrop-blur-md;
  background-color: rgba(10, 10, 10, 0.92);
  box-shadow: none;
}
.dark #header.scroll > div:first-child,
#header.scroll.dark > div:first-child {
  @apply bg-page border-b border-white/[0.06];
  background-color: rgba(10, 10, 10, 0.92);
  backdrop-filter: blur(12px);
  box-shadow: none;
}

#header.expanded nav {
  position: fixed;
  top: 70px;
  left: 0;
  right: 0;
  bottom: 70px !important;
  padding: 0 5px;
}

.dropdown:focus .dropdown-menu,
.dropdown:focus-within .dropdown-menu,
.dropdown:hover .dropdown-menu {
  display: block;
}

[astro-icon].icon-light > * {
  stroke-width: 1.2;
}

[astro-icon].icon-bold > * {
  stroke-width: 2.4;
}

[data-aw-toggle-menu] path {
  @apply transition;
}
[data-aw-toggle-menu].expanded g > path:first-child {
  @apply -rotate-45 translate-y-[15px] translate-x-[-3px];
}

[data-aw-toggle-menu].expanded g > path:last-child {
  @apply rotate-45 translate-y-[-8px] translate-x-[14px];
}

.dd *:first-child {
  margin-top: 0;
}

/* ===== Geometric SVG Animations ===== */

@media (prefers-reduced-motion: no-preference) {
  .geo-spin-slow {
    animation: geoSpin 60s linear infinite;
    transform-origin: 250px 250px;
