  0%,
  100% {
    opacity: 0.15;
  }
  50% {
    opacity: 0.45;
  }
}

@keyframes geoPulseDot {
  0%,
  100% {
    opacity: 0.3;
    r: 3;
  }
  50% {
    opacity: 0.7;
    r: 4.5;
  }
